using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Collections.Generic;
using System.Web.Script.Serialization;
namespace SplifyWin {
 public static partial class VkTurnOptions {
  public const string Marker="MCRF_TURN_OPTIONS_V1";
  public static VkTurnPreferences ForNode(VkTurnPreferences p,ServerNode n){if(n.TurnPreferences!=null){var json=new JavaScriptSerializer();p.Servers[n.Id]=json.Deserialize<VkTurnServerPreferences>(json.Serialize(n.TurnPreferences));}var settings=VkTurnSettings.Server(p,n.Id);if(String.IsNullOrEmpty(settings.CaptchaMode))settings.CaptchaMode="auto";return p;}
  public static string Share(ServerNode node,string root){if(!new[]{"csqtt","wdtt","qwdtt"}.Contains(node.Protocol))return CsqttGenerations.Share(node);var p=VkTurnSettings.Server(ForNode(VkTurnSettings.Load(root),node),node.Id);Validate(node,p);var json=new JavaScriptSerializer().Serialize(new{version=1,link=CsqttGenerations.Share(node),name=node.Name,settings=p});return "mcrf-turn://v1/"+Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(json)).TrimEnd('=').Replace('+','-').Replace('/','_');}
  public static List<ServerNode> ReadEnvelope(string value){if(value.Length>131072||!value.StartsWith("mcrf-turn://v1/",StringComparison.Ordinal))throw new FormatException("Некорректный профиль MCRF TURN.");string b=value.Substring(15).Replace('-','+').Replace('_','/');var json=new JavaScriptSerializer();var d=json.Deserialize<Dictionary<string,object>>(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(b.PadRight((b.Length+3)/4*4,'='))));if(Convert.ToInt32(d["version"])!=1)throw new FormatException("Версия профиля TURN не поддерживается.");string link=Convert.ToString(d["link"]);if(!new[]{"csqtt://","wdtt://","qwdtt://"}.Any(prefix=>link.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)))throw new FormatException("Некорректный протокол профиля TURN.");var nodes=Links.Read(link);if(nodes.Count!=1)throw new FormatException("Некорректный профиль TURN.");var n=nodes[0];n.Name=Convert.ToString(d["name"]);if(String.IsNullOrWhiteSpace(n.Name)||n.Name.Length>256)throw new FormatException("Некорректное название профиля.");n.TurnPreferences=json.Deserialize<VkTurnServerPreferences>(json.Serialize(d["settings"]));Validate(n,n.TurnPreferences);return nodes;}
  public static string Kind(ServerNode n){return n.Protocol=="csqtt"&&CsqttGenerations.For(n).Id=="2.5"?"csqtt25":n.Protocol;}
  public static string MeasurementHost(ServerNode node,VkTurnPreferences preferences){if(node==null)throw new ArgumentNullException("node");if(!new[]{"csqtt","wdtt","qwdtt"}.Contains(node.Protocol))return node.Host;var settings=VkTurnSettings.Server(ForNode(preferences??new VkTurnPreferences(),node),node.Id);Validate(node,settings);return ServerHost(settings,node.Host);}
  public static VkTurnServerPreferences FromLink(string link){if(Csqtt25Link.IsSealed(link))return null;Uri u;if(!Uri.TryCreate(link,UriKind.Absolute,out u))return null;var q=System.Web.HttpUtility.ParseQueryString(u.Query);var p=new VkTurnServerPreferences();foreach(string key in new[]{"obfs","fingerprint","turn_transport","vk_auth_mode","go_dns","raw_port","client_ids","allow_hash_redistribution","generation","salt","vk_token","vk_hash_mode","extra_streams","custom_turn_ips","custom_vk_client_id","custom_vk_client_secret","vkcalls_preflight","turn_stream_first","device_id"})if(q[key]!=null)p.Options[key]=q[key];if(q["turn_tcp"]!=null){if(!new[]{"true","false","1","0"}.Contains(q["turn_tcp"]))throw new FormatException("Некорректный TURN TCP.");p.Options["turn_transport"]=q["turn_tcp"]=="true"||q["turn_tcp"]=="1"?"tcp":"udp";}if(q["vk_anon_path"]!=null)p.Options["vk_auth_mode"]=q["vk_anon_path"];if(q["captcha_mode"]!=null)p.CaptchaMode=q["captcha_mode"]=="wv"?"manual":q["captcha_mode"];if(q["rt_masque"]!=null){if(!new[]{"true","false"}.Contains(q["rt_masque"]))throw new FormatException("Некорректный MASQUE.");p.Masque=q["rt_masque"]=="true";}if(q["turn_sni"]!=null)p.TurnSni=q["turn_sni"];return p.Options.Count>0||p.Masque||p.TurnSni!=null||p.CaptchaMode!=null?p:null;}
  public static string Value(VkTurnServerPreferences p,string key,string fallback=""){string v;return p!=null&&p.Options!=null&&p.Options.TryGetValue(key,out v)?v:fallback;}
  public static string ServerHost(VkTurnServerPreferences p,string fallback){string value=Value(p,"server",fallback);return value!=null&&value.Length>2&&value[0]=='['&&value[value.Length-1]==']'&&Uri.CheckHostName(value)==UriHostNameType.IPv6?value.Substring(1,value.Length-2):value;}
  public static string[] Calls(string value){return System.Text.RegularExpressions.Regex.Split(value??"",@"[\s,;]+").Where(s=>s.Length>0).Select(s=>{if(s.StartsWith("https://",StringComparison.OrdinalIgnoreCase))return VkCalls.CallHash(s);if(!System.Text.RegularExpressions.Regex.IsMatch(s,@"^[A-Za-z0-9_=/+\-]{16,2048}$"))throw new FormatException("Некорректный хеш звонка VK.");return s;}).Distinct(StringComparer.Ordinal).ToArray();}
  public static bool Flag(VkTurnServerPreferences p,string key,bool fallback=false){return Value(p,key,fallback?"true":"false")=="true";}
  public static int Number(VkTurnServerPreferences p,string key,int fallback){string v=Value(p,key);return String.IsNullOrEmpty(v)?fallback:Int32.Parse(v,System.Globalization.CultureInfo.InvariantCulture);}
  public static void Validate(ServerNode node,VkTurnServerPreferences p){
   if(p==null||p.Options==null||p.Options.Count>40||p.Options.Any(pair=>pair.Value==null))throw new FormatException("Некорректные параметры подключения.");string kind=Kind(node),generation=kind=="csqtt"?CsqttGenerations.For(node).Id:"";
   if(!new[]{"","auto","manual","rjs"}.Contains(p.CaptchaMode??"")||!new[]{"","raw","wireguard"}.Contains(p.QwdttMode??"")||p.CallCount<1||p.CallCount>(VkTurnSettings.MaximumCalls(node)))throw new FormatException("Некорректные параметры капчи, режима или количества звонков.");if(p.AutoCalls&&Value(p,"hashes").Length>0)throw new FormatException("Для автоматической группы очистите ручные звонки: ваши ссылки имеют приоритет.");if(!String.IsNullOrEmpty(p.TurnSni)&&Uri.CheckHostName(p.TurnSni)!=UriHostNameType.Dns)throw new FormatException("TURN SNI: домен без схемы, порта и пути.");
   string[] allowed=new[]{"server","server_port","password","hashes","device_id","fingerprint"}.Concat(kind=="wdtt"?new[]{"wg_port","local_port","client_ids","custom_vk_client_id","custom_vk_client_secret","vkcalls_preflight","turn_stream_first"}:kind=="qwdtt"?new[]{"obfs","turn_transport","vk_auth_mode","go_dns","raw_port"}:kind=="csqtt25"?new[]{"obfs","turn_transport","vk_auth_mode","client_ids","allow_hash_redistribution","generation","salt","vk_token","vk_hash_mode","custom_turn_ips","implementation"}:new[]{"obfs","turn_transport","vk_auth_mode","vk_token","vk_hash_mode","extra_streams"}).ToArray();
   foreach(var kv in p.Options){if(!allowed.Contains(kv.Key)||kv.Value==null||kv.Value.Length>16384||kv.Value.Any(c=>c=='\0'))throw new FormatException("Неизвестный или слишком длинный параметр подключения.");if(kv.Key!="hashes"&&kv.Key!="custom_turn_ips"&&kv.Value.Any(Char.IsControl))throw new FormatException("Недопустимые символы параметра "+kv.Key);}
   foreach(string key in new[]{"server_port","raw_port","wg_port","local_port"}){string v=Value(p,key);int n;if(v.Length>0&&(!Int32.TryParse(v,out n)||n<1||n>65535))throw new FormatException("Порт должен быть от 1 до 65535: "+key);}
   if(Value(p,"server").Length>0&&Uri.CheckHostName(Value(p,"server"))==UriHostNameType.Unknown)throw new FormatException("Укажите домен или IP без схемы и порта.");
   if(Value(p,"password").Length>4096||Value(p,"vk_token").Length>4096||Value(p,"device_id").Length>256||Value(p,"salt").Length>1024)throw new FormatException("Слишком длинное секретное поле или идентификатор.");if(p.Workers!=0&&(kind=="csqtt25"?p.Workers<3:p.Workers%9!=0))throw new FormatException("Недопустимый шаг числа потоков.");
   foreach(string key in new[]{"allow_hash_redistribution","extra_streams","vkcalls_preflight","turn_stream_first"})if(Value(p,key).Length>0&&!new[]{"true","false"}.Contains(Value(p,key)))throw new FormatException("Некорректный переключатель "+key);
   Action<string,string[]> choice=(key,values)=>{if(Value(p,key).Length>0&&!values.Contains(Value(p,key)))throw new FormatException("Неподдерживаемое значение "+key);};
   choice("obfs",kind=="csqtt25"?new[]{"unified","audio","video"}:new[]{"audio","video"});if(kind!="csqtt25")choice("fingerprint",kind=="wdtt"?new[]{"android","chrome","firefox","safari","ios"}:new[]{"chrome","firefox","safari"});else if(Value(p,"fingerprint").Length>64)throw new FormatException("Отпечаток TLS: до 64 символов.");choice("turn_transport",new[]{"udp","tcp"});choice("vk_auth_mode",new[]{"vkcalls","legacy","auto_js"});choice("vk_hash_mode",new[]{"manual","auto_js"});choice("go_dns",new[]{"yandex","google","cloudflare","doh-yandex","doh-google","doh-cloudflare"});choice("implementation",new[]{"swg-panel-2.5.1","amurcanov-2.5.0","rebirth-2.5.0","compatible-2.5"});
   if(generation=="2.0"&&Value(p,"turn_transport")=="tcp")throw new FormatException("CSQTT 2.0 поддерживает только TURN UDP.");
   if(kind!="csqtt25"&&p.Options.ContainsKey("custom_turn_ips"))throw new FormatException("Собственные TURN IP доступны в CSQTT 2.5.");
   if(node.Protocol=="csqtt"&&TurnProfile.Parse(node.Link).Hashes.Length>VkTurnSettings.MaximumCalls(node))throw new FormatException("Это поколение CSQTT не поддерживает столько звонков; выберите CSQTT 2.5.");if(Value(p,"hashes").Length>0&&Calls(Value(p,"hashes")).Length>(VkTurnSettings.MaximumCalls(node)))throw new FormatException("Слишком много звонков для этого протокола.");
   string hashMode=Value(p,"vk_hash_mode","manual"),auth=Value(p,"vk_auth_mode","vkcalls"),token=Value(p,"vk_token");if(hashMode=="auto_js"&&(kind!="csqtt25"&&generation!="2.1.9"||kind=="csqtt25"&&token.Length==0||Value(p,"hashes").Length>0||p.AutoCalls))throw new FormatException("Auto JS: нужен токен или привязанный VK (2.1.9), без ручных звонков и автоматических групп host.");if(auth=="auto_js"&&hashMode!="auto_js")throw new FormatException("Авторизация Auto JS требует соответствующего источника звонков.");if(hashMode=="manual"&&token.Length>0)throw new FormatException("Токен нельзя смешивать с ручным источником звонков.");
   string ids=Value(p,"client_ids");if(ids.Length>0&&(ids.Split(',').Length>32||ids.Split(',').Any(s=>!System.Text.RegularExpressions.Regex.IsMatch(s.Trim(),@"^[0-9]{1,20}$"))))throw new FormatException("Client IDs: до 32 числовых ID через запятую.");
   string customId=Value(p,"custom_vk_client_id"),secret=Value(p,"custom_vk_client_secret");if((customId.Length>0||secret.Length>0)&&(!System.Text.RegularExpressions.Regex.IsMatch(customId,@"^[0-9]{1,20}$")||secret.Length==0||secret.Length>4096))throw new FormatException("Собственные Client ID и Client secret VK задаются вместе.");
   if(p.Options.ContainsKey("generation")){long n;if(!Int64.TryParse(Value(p,"generation"),out n)||n<0)throw new FormatException("Поколение пароля должно быть неотрицательным числом.");}
   if(Value(p,"custom_turn_ips").Length>0){var ips=System.Text.RegularExpressions.Regex.Split(Value(p,"custom_turn_ips"),@"[\s,;]+").Where(s=>s.Length>0).ToArray();if(ips.Length>256||ips.Distinct().Count()!=ips.Length)throw new FormatException("До 256 уникальных TURN IP.");foreach(string s in ips){IPAddress ip;if(!IPAddress.TryParse(s,out ip)||IPAddress.IsLoopback(ip)||ip.Equals(IPAddress.Any)||ip.Equals(IPAddress.IPv6Any)||ip.IsIPv6Multicast)throw new FormatException("Некорректный TURN IP.");}}
   if(p.Workers<0||p.Workers>(kind=="csqtt25"?100:kind=="csqtt"?126:kind=="wdtt"?108:162))throw new FormatException("Число потоков не поддерживается этим протоколом.");if(kind=="csqtt"&&p.Workers>72&&!Flag(p,"extra_streams"))throw new FormatException("Для более 72 потоков разрешите дополнительные потоки.");
  }
  public static TurnProfile Apply(ServerNode node,TurnProfile p,VkTurnServerPreferences s){Validate(node,s);p.Host=ServerHost(s,p.Host);p.Port=Number(s,"server_port",p.Port);p.Password=Value(s,"password",p.Password);if(s.Options.ContainsKey("hashes"))p.Hashes=Calls(Value(s,"hashes"));p.VkToken=Value(s,"vk_token",p.VkToken);return p;}
  public static string Arguments(VkTurnServerPreferences s,string kind){var flags=new Dictionary<string,string>();if(kind=="wdtt"){flags["fingerprint"]=Value(s,"fingerprint","android");flags["vkcalls-preflight"]=Value(s,"vkcalls_preflight","true");flags["turn-stream-first"]=Value(s,"turn_stream_first","false");if(Value(s,"client_ids").Length>0)flags["client-ids"]=Value(s,"client_ids");}else{flags["obfs"]=Value(s,"obfs","audio");flags["vk-anon-path"]=Value(s,"vk_auth_mode","vkcalls");flags["go-dns"]=Value(s,"go_dns","yandex");flags["turn-tcp"]=Value(s,"turn_transport","tcp")=="tcp"?"true":"false";if(Value(s,"fingerprint").Length>0)flags["fingerprint"]=Value(s,"fingerprint");}return String.Concat(flags.Select(kv=>" -"+kv.Key+"="+ZapretRuntime.Quote(kv.Value)));}
  public static bool NativeOptions(VkTurnServerPreferences s){return s.Options!=null&&s.Options.Keys.Any(k=>!new[]{"server","server_port","password","hashes","wg_port","local_port","raw_port"}.Contains(k));}
  public static void RequireModule(string exe){if(String.IsNullOrEmpty(exe)||!File.Exists(exe)||!System.Text.Encoding.ASCII.GetString(File.ReadAllBytes(exe)).Contains(Marker))throw new InvalidOperationException("Обновите дополнительный движок: установленный модуль не поддерживает расширенные настройки VK TURN.");}
 }
